package gg.eternal.core.config;
import com.google.gson.*; import net.fabricmc.loader.api.FabricLoader; import java.nio.file.*; import java.nio.charset.StandardCharsets; import java.util.*;
public final class CoreConfig { public static final CoreConfig INSTANCE=new CoreConfig(); public final Map<String,Boolean> enabled=new LinkedHashMap<>(); public final Map<String,int[]> positions=new LinkedHashMap<>(); private final Path file=FabricLoader.getInstance().getConfigDir().resolve("eternal-core.json"); private CoreConfig(){for(String n:new String[]{"FPS","CPS","Keystrokes","Coordinates","Ping","Speed","Direction","Memory","Session"})enabled.put(n,true);load();} public boolean on(String n){return enabled.getOrDefault(n,true);} public void toggle(String n){enabled.put(n,!on(n));save();} public int[] pos(String n,int x,int y){return positions.computeIfAbsent(n,k->new int[]{x,y});} public void pos(String n,int x,int y){positions.put(n,new int[]{x,y});save();} public void reset(){positions.clear();save();} private void load(){try{if(!Files.exists(file))return;JsonObject o=JsonParser.parseString(Files.readString(file)).getAsJsonObject();if(o.has("enabled"))for(var e:o.getAsJsonObject("enabled").entrySet())enabled.put(e.getKey(),e.getValue().getAsBoolean());if(o.has("positions"))for(var e:o.getAsJsonObject("positions").entrySet()){JsonArray a=e.getValue().getAsJsonArray();positions.put(e.getKey(),new int[]{a.get(0).getAsInt(),a.get(1).getAsInt()});}}catch(Exception ignored){}} public void save(){try{Files.createDirectories(file.getParent());JsonObject o=new JsonObject(),en=new JsonObject(),ps=new JsonObject();enabled.forEach(en::addProperty);positions.forEach((k,v)->{JsonArray a=new JsonArray();a.add(v[0]);a.add(v[1]);ps.add(k,a);});o.add("enabled",en);o.add("positions",ps);Files.writeString(file,new GsonBuilder().setPrettyPrinting().create().toJson(o),StandardCharsets.UTF_8);}catch(Exception ignored){}} }
